static class Pipeline {
    public static long authorize(long amount, long available, long daily_used, long daily_limit, bool blocked) {
        if (blocked) {
            return (-1);
        }
        if ((amount <= 0)) {
            return (-2);
        }
        if ((daily_used <= 0)) {
            return (-3);
        }
        long remaining = (daily_limit - daily_used);
        if ((remaining <= amount)) {
            return (-4);
        }
        if ((available < amount)) {
            return (-5);
        }
        long reserved = (available - amount);
        if ((reserved < 200)) {
            return 1;
        }
        return 0;
    }

public static long capture(long authorized, long requested, long captured, bool expired) {
    if (expired) {
        return (-1);
    }
    if ((requested < 0)) {
        return (-2);
    }
    long remaining = (authorized - captured);
    if ((remaining <= 0)) {
        return (-3);
    }
    if ((requested > remaining)) {
        return (-4);
    }
    long total = (captured + requested);
    if ((total >= authorized)) {
        return 2;
    }
    if ((total < authorized)) {
        return 1;
    }
    return (-5);
}

public static long settlement_net(long[] captures, long[] refunds, long fee_bps) {
    if (((fee_bps < 0) || (fee_bps > 9000))) {
        return (-1);
    }
    long gross = 0;
    for (long i = 0; i < captures.Length; i++) {
        if ((captures[(int)(i)] < 0)) {
            return (-2);
        }
        gross += captures[(int)(i)];
    }
    long returned = 0;
    for (long i = 0; i < refunds.Length; i++) {
        if ((refunds[(int)(i)] < 0)) {
            return (-3);
        }
        returned += refunds[(int)(i)];
    }
    if ((returned > gross)) {
        return (-4);
    }
    long net = (gross - returned);
    long fee = ((net * fee_bps) / 10000);
    return (net - fee);
}

public static long dispute_reserve(long[] amounts, long[] ages, long max_age) {
    if ((amounts.Length != ages.Length)) {
        return (-1);
    }
    long total = 0;
    for (long i = 0; i < amounts.Length; i++) {
        if ((ages[(int)(i)] < 0)) {
            return (-2);
        }
        if ((ages[(int)(i)] >= max_age)) {
            continue;
        }
        if ((amounts[(int)(i)] <= 0)) {
            continue;
        }
        total += amounts[(int)(i)];
    }
    if ((total == 0)) {
        return 0;
    }
    return (total + (total / 10));
}

public static long retry_delay(long attempt, long initial, long cap, long jitter) {
    if (((attempt < 0) || (initial <= 0))) {
        return (-1);
    }
    long delay = initial;
    long count = 0;
    while ((count < attempt)) {
        if ((delay > (cap / 2))) {
            delay = cap;
            break;
        }
        delay *= 2;
        count += 1;
    }
    long bounded = System.Math.Min(delay, cap);
    if ((jitter < 0)) {
        jitter = 0;
    }
    return System.Math.Min((bounded + jitter), cap);
}

public static long retryable(long status, long attempt, long maximum, bool idempotent) {
    if ((!idempotent)) {
        return 0;
    }
    if ((attempt > maximum)) {
        return 0;
    }
    if ((status == 429)) {
        return 1;
    }
    if ((status == 408)) {
        return 1;
    }
    if ((status >= 500)) {
        if ((status < 600)) {
            return 1;
        }
    }
    if ((status == 0)) {
        return 1;
    }
    return 0;
}

public static long pick_batch(long[] stock, long needed, long max_locations) {
    long remaining = needed;
    long visited = 0;
    for (long i = 0; i < stock.Length; i++) {
        if ((remaining <= 0)) {
            break;
        }
        if ((visited >= max_locations)) {
            return (-remaining);
        }
        if ((stock[(int)(i)] < 0)) {
            continue;
        }
        long picked = System.Math.Min(stock[(int)(i)], remaining);
        remaining -= picked;
        visited += 1;
    }
    if ((remaining > 0)) {
        return (-remaining);
    }
    return visited;
}

public static long reconcile_stock(long[] expected, long[] counted, long tolerance) {
    if ((expected.Length != counted.Length)) {
        return (-1);
    }
    long discrepancy = 0;
    long critical = 0;
    for (long i = 0; i < expected.Length; i++) {
        long delta = System.Math.Abs((counted[(int)(i)] - expected[(int)(i)]));
        if ((delta == 0)) {
            continue;
        }
        discrepancy += delta;
        if ((delta >= tolerance)) {
            critical += 1;
        }
    }
    if ((critical > 0)) {
        return (-critical);
    }
    return discrepancy;
}

public static long cancellation_fee(long paid, bool dispatched, long hours, long fee_bps) {
    if ((paid < 0)) {
        return (-1);
    }
    if (dispatched) {
        return paid;
    }
    if ((hours < 0)) {
        return (-2);
    }
    if ((hours <= 2)) {
        return 0;
    }
    long fee = ((paid * fee_bps) / 10000);
    if ((fee < 100)) {
        fee = System.Math.Min(paid, 100);
    }
    return System.Math.Min(fee, paid);
}

public static long authenticate(long now, long expires, long issued, bool revoked) {
    if (revoked) {
        return (-1);
    }
    if ((issued > (now + 30))) {
        return (-2);
    }
    if ((expires <= issued)) {
        return (-3);
    }
    if ((now > expires)) {
        return (-4);
    }
    long age = (now - issued);
    if ((age < 0)) {
        return 1;
    }
    if ((age > 86400)) {
        return 2;
    }
    return 0;
}

public static long login_lockout(long[] failures, long now, long window, long maximum) {
    long recent = 0;
    long earliest = now;
    for (long i = 0; i < failures.Length; i++) {
        if ((failures[(int)(i)] > now)) {
            continue;
        }
        long age = (now - failures[(int)(i)]);
        if ((age <= window)) {
            recent += 1;
            earliest = System.Math.Min(earliest, failures[(int)(i)]);
        }
    }
    if ((recent >= maximum)) {
        return System.Math.Max(1, ((earliest + window) - now));
    }
    return 0;
}

public static long permission(long role, bool owner, bool suspended, bool write) {
    if (suspended) {
        return 0;
    }
    if ((role == 3)) {
        return 1;
    }
    if (write) {
        if ((role < 1)) {
            return 0;
        }
        if ((!owner)) {
            return 0;
        }
    }
    if ((role == 0)) {
        return 0;
    }
    return 1;
}

public static long session_refresh(long now, long last_seen, long issued, long idle, long lifetime) {
    if ((last_seen < issued)) {
        return (-1);
    }
    if ((now < last_seen)) {
        return (-2);
    }
    long idle_age = (now - last_seen);
    if ((idle_age > idle)) {
        return (-3);
    }
    long total_age = (now - issued);
    if ((total_age >= lifetime)) {
        return (-4);
    }
    long remaining = System.Math.Min((idle - idle_age), (lifetime - total_age));
    return System.Math.Max(0, remaining);
}

public static long cache_admission(long size, long capacity, long used, long hit_rate) {
    if ((size <= 0)) {
        return (-1);
    }
    if ((size > (capacity / 2))) {
        return 0;
    }
    long available = (capacity - used);
    if ((size <= available)) {
        return 1;
    }
    if ((hit_rate < 20)) {
        return 0;
    }
    long required = (size - available);
    if ((required > (capacity / 10))) {
        return 0;
    }
    return 2;
}

public static long lease_job(long now, long lease_until, long attempts, long max_attempts, bool cancelled) {
    if (cancelled) {
        return (-1);
    }
    if ((attempts >= max_attempts)) {
        return (-2);
    }
    if ((lease_until > now)) {
        return 0;
    }
    long duration = 30;
    if ((attempts > 3)) {
        duration = 60;
    }
    if ((attempts > 5)) {
        duration = 120;
    }
    return (now + duration);
}

public static long circuit_state(long failures, long successes, long elapsed, long cooldown, long probes) {
    if (((successes >= probes) && (probes > 0))) {
        return 0;
    }
    if ((elapsed >= cooldown)) {
        return 2;
    }
    return 1;
}

public static long health_score(long[] latencies, long errors, long requests) {
    if ((requests <= 0)) {
        return 100;
    }
    if ((errors > requests)) {
        return (-1);
    }
    long slow = 0;
    for (long i = 0; i < latencies.Length; i++) {
        if ((latencies[(int)(i)] > 800)) {
            slow += 1;
        }
    }
    long availability = (((requests - errors) * 100) / requests);
    long penalty = System.Math.Min((slow * 2), 30);
    long score = (availability - penalty);
    return System.Math.Max(0, score);
}

public static long circuit_state(long failures, long successes, long elapsed, long cooldown, long probes) {
    if ((failures < 5)) {
        return 0;
    }
    if ((elapsed < cooldown)) {
        return 1;
    }
    if ((probes == 0)) {
        return 2;
    }
    if ((successes >= probes)) {
        return 0;
    }
    if ((failures > probes)) {
        return 1;
    }
    return 2;
}

