blocks.source:
func authorize(amount int64, available int64, daily_used int64, daily_limit int64, blocked bool) int64 {
    if blocked {
        return (-1)
    }
    if (amount <= 0) {
        return (-2)
    }
    if (daily_used <= 0) {
        return (-3)
    }
    var remaining int64 = (daily_limit - daily_used)
    if (remaining <= amount) {
        return (-4)
    }
    if (available < amount) {
        return (-5)
    }
    var reserved int64 = (available - amount)
    if (reserved < 200) {
        return 1
    }
    return 0
}

func capture(authorized int64, requested int64, captured int64, expired bool) int64 {
    if expired {
        return (-1)
    }
    if (requested < 0) {
        return (-2)
    }
    var remaining int64 = (authorized - captured)
    if (remaining <= 0) {
        return (-3)
    }
    if (requested > remaining) {
        return (-4)
    }
    var total int64 = (captured + requested)
    if (total >= authorized) {
        return 2
    }
    if (total < authorized) {
        return 1
    }
    return (-5)
}

func settlement_net(captures []int64, refunds []int64, fee_bps int64) int64 {
    if ((fee_bps < 0) || (fee_bps > 9000)) {
        return (-1)
    }
    var gross int64 = 0
    for i := int64(0); i < int64(len(captures)); i++ {
        if (captures[i] < 0) {
            return (-2)
        }
        gross += captures[i]
    }
    var returned int64 = 0
    for i := int64(0); i < int64(len(refunds)); i++ {
        if (refunds[i] < 0) {
            return (-3)
        }
        returned += refunds[i]
    }
    if (returned > gross) {
        return (-4)
    }
    var net int64 = (gross - returned)
    var fee int64 = ((net * fee_bps) / 10000)
    return (net - fee)
}

func dispute_reserve(amounts []int64, ages []int64, max_age int64) int64 {
    if (int64(len(amounts)) != int64(len(ages))) {
        return (-1)
    }
    var total int64 = 0
    for i := int64(0); i < int64(len(amounts)); i++ {
        if (ages[i] < 0) {
            return (-2)
        }
        if (ages[i] >= max_age) {
            continue
        }
        if (amounts[i] <= 0) {
            continue
        }
        total += amounts[i]
    }
    if (total == 0) {
        return 0
    }
    return (total + (total / 10))
}

func retry_delay(attempt int64, initial int64, cap int64, jitter int64) int64 {
    if ((attempt < 0) || (initial <= 0)) {
        return (-1)
    }
    var delay int64 = initial
    var count int64 = 0
    for (count < attempt) {
        if (delay > (cap / 2)) {
            delay = cap
            break
        }
        delay *= 2
        count += 1
    }
    var bounded int64 = min64(delay, cap)
    if (jitter < 0) {
        jitter = 0
    }
    return min64((bounded + jitter), cap)
}

func retryable(status int64, attempt int64, maximum int64, idempotent bool) int64 {
    if (!idempotent) {
        return 0
    }
    if (attempt > maximum) {
        return 0
    }
    if (status == 429) {
        return 1
    }
    if (status == 408) {
        return 1
    }
    if (status >= 500) {
        if (status < 600) {
            return 1
        }
    }
    if (status == 0) {
        return 1
    }
    return 0
}

func pick_batch(stock []int64, needed int64, max_locations int64) int64 {
    var remaining int64 = needed
    var visited int64 = 0
    for i := int64(0); i < int64(len(stock)); i++ {
        if (remaining <= 0) {
            break
        }
        if (visited >= max_locations) {
            return (-remaining)
        }
        if (stock[i] < 0) {
            continue
        }
        var picked int64 = min64(stock[i], remaining)
        remaining -= picked
        visited += 1
    }
    if (remaining > 0) {
        return (-remaining)
    }
    return visited
}

func reconcile_stock(expected []int64, counted []int64, tolerance int64) int64 {
    if (int64(len(expected)) != int64(len(counted))) {
        return (-1)
    }
    var discrepancy int64 = 0
    var critical int64 = 0
    for i := int64(0); i < int64(len(expected)); i++ {
        var delta int64 = abs64((counted[i] - expected[i]))
        if (delta == 0) {
            continue
        }
        discrepancy += delta
        if (delta >= tolerance) {
            critical += 1
        }
    }
    if (critical > 0) {
        return (-critical)
    }
    return discrepancy
}

func cancellation_fee(paid int64, dispatched bool, hours int64, fee_bps int64) int64 {
    if (paid < 0) {
        return (-1)
    }
    if dispatched {
        return paid
    }
    if (hours < 0) {
        return (-2)
    }
    if (hours <= 2) {
        return 0
    }
    var fee int64 = ((paid * fee_bps) / 10000)
    if (fee < 100) {
        fee = min64(paid, 100)
    }
    return min64(fee, paid)
}

func authenticate(now int64, expires int64, issued int64, revoked bool) int64 {
    if revoked {
        return (-1)
    }
    if (issued > (now + 30)) {
        return (-2)
    }
    if (expires <= issued) {
        return (-3)
    }
    if (now > expires) {
        return (-4)
    }
    var age int64 = (now - issued)
    if (age < 0) {
        return 1
    }
    if (age > 86400) {
        return 2
    }
    return 0
}

func login_lockout(failures []int64, now int64, window int64, maximum int64) int64 {
    var recent int64 = 0
    var earliest int64 = now
    for i := int64(0); i < int64(len(failures)); i++ {
        if (failures[i] > now) {
            continue
        }
        var age int64 = (now - failures[i])
        if (age <= window) {
            recent += 1
            earliest = min64(earliest, failures[i])
        }
    }
    if (recent >= maximum) {
        return max64(1, ((earliest + window) - now))
    }
    return 0
}

func permission(role int64, owner bool, suspended bool, write bool) int64 {
    if suspended {
        return 0
    }
    if (role == 3) {
        return 1
    }
    if write {
        if (role < 1) {
            return 0
        }
        if (!owner) {
            return 0
        }
    }
    if (role == 0) {
        return 0
    }
    return 1
}

func session_refresh(now int64, last_seen int64, issued int64, idle int64, lifetime int64) int64 {
    if (last_seen < issued) {
        return (-1)
    }
    if (now < last_seen) {
        return (-2)
    }
    var idle_age int64 = (now - last_seen)
    if (idle_age > idle) {
        return (-3)
    }
    var total_age int64 = (now - issued)
    if (total_age >= lifetime) {
        return (-4)
    }
    var remaining int64 = min64((idle - idle_age), (lifetime - total_age))
    return max64(0, remaining)
}

func cache_admission(size int64, capacity int64, used int64, hit_rate int64) int64 {
    if (size <= 0) {
        return (-1)
    }
    if (size > (capacity / 2)) {
        return 0
    }
    var available int64 = (capacity - used)
    if (size <= available) {
        return 1
    }
    if (hit_rate < 20) {
        return 0
    }
    var required int64 = (size - available)
    if (required > (capacity / 10)) {
        return 0
    }
    return 2
}

func lease_job(now int64, lease_until int64, attempts int64, max_attempts int64, cancelled bool) int64 {
    if cancelled {
        return (-1)
    }
    if (attempts >= max_attempts) {
        return (-2)
    }
    if (lease_until > now) {
        return 0
    }
    var duration int64 = 30
    if (attempts > 3) {
        duration = 60
    }
    if (attempts > 5) {
        duration = 120
    }
    return (now + duration)
}

func circuit_state(failures int64, successes int64, elapsed int64, cooldown int64, probes int64) int64 {
    if ((successes >= probes) && (probes > 0)) {
        return 0
    }
    if (elapsed >= cooldown) {
        return 2
    }
    return 1
}

func health_score(latencies []int64, errors int64, requests int64) int64 {
    if (requests <= 0) {
        return 100
    }
    if (errors > requests) {
        return (-1)
    }
    var slow int64 = 0
    for i := int64(0); i < int64(len(latencies)); i++ {
        if (latencies[i] > 800) {
            slow += 1
        }
    }
    var availability int64 = (((requests - errors) * 100) / requests)
    var penalty int64 = min64((slow * 2), 30)
    var score int64 = (availability - penalty)
    return max64(0, score)
}

func circuit_state(failures int64, successes int64, elapsed int64, cooldown int64, probes int64) int64 {
    if (failures < 5) {
        return 0
    }
    if (elapsed < cooldown) {
        return 1
    }
    if (probes == 0) {
        return 2
    }
    if (successes >= probes) {
        return 0
    }
    if (failures > probes) {
        return 1
    }
    return 2
}

